# Generates apps/api/internal/adminwrites/testdata/contacts.seed.sql and the cases files of the Admin contact-change and
# password-reset writes:
#   resetreview.cases.json     POST /api/password-reset-requests/{requestId}            (issue a link, or decline)
#   contactcreate.cases.json   POST /api/contact-change-requests                         (the owner enters a request)
#   contactdecide.cases.json   POST /api/contact-change-requests/{requestId}/{approve|decline|check|retry}
# The cases are data; the *.golden.json files are captured from the TypeScript by capture-writes-contacts.test.mjs, never
# generated here. Edit this file, run `python3 apps/api/testdata/tools/gen-writes-admin-contact-cases.py`, then rerun the
# capture. The seed is the Admin player writes' seed (players.seed.sql, itself generated by
# gen-writes-admin-players-cases.py) plus the password-reset requests below.
import json
import os

