SUB = lambda n: "f4000000-0000-4000-8000-%012d" % n  # a player account's auth subject: the player's number
RQ = lambda n: "b1000000-0000-4000-8000-%012d" % n  # contact-change requests (1 to 10 are seeded)
CMD = lambda n: "b2000000-0000-4000-8000-%012d" % n  # their command ids
REF = lambda n: "b4000000-0000-4000-8000-%012d" % n  # provider operation refs
RS = lambda n: "b3000000-0000-4000-8000-%012d" % n  # password-reset requests
TS = "TIMESTAMPTZ '2026-11-01 00:00:00+00'"
NEWCMD = lambda n: "c0000000-0000-4000-8000-%012d" % n

# ---------------------------------------------------------------- seed
base = open(os.path.join(OUT, "players.seed.sql")).read()
