    "  ('%s', 'bob@example.test', '%s', 'issued', TIMESTAMPTZ '2026-11-17 00:00:00+00', '%s', TIMESTAMPTZ '2026-11-17 01:00:00+00', '%s', sha256('old-bob-link'::bytea), %s)," % (RS(102), BOB, ADMIN1, SUB(2), TS),
    "  ('%s', 'carla@example.test', '%s', 'declined', TIMESTAMPTZ '2026-11-16 00:00:00+00', '%s', TIMESTAMPTZ '2026-11-16 01:00:00+00', NULL, NULL, %s)," % (RS(103), CARLA, ADMIN1, TS),
    "  ('%s', 'hana@example.test', '%s', 'pending', TIMESTAMPTZ '2026-11-18 01:00:00+00', NULL, NULL, NULL, NULL, %s)," % (RS(104), HANA, TS),
    "  ('%s', 'hana@example.test', '%s', 'issued', TIMESTAMPTZ '2026-11-15 00:00:00+00', '%s', TIMESTAMPTZ '2026-11-15 01:00:00+00', '%s', sha256('old-hana-link'::bytea), %s)," % (RS(105), HANA, ADMIN1, SUB(8), TS),
