r("issue_ownership_missing", [step("POST", rp(RS(101)), {"action": "issue"})])
r("issue_ownership_is_a_string", [step("POST", rp(RS(101)), {"action": "issue", "ownershipVerified": "true"})])
r("issue_ownership_is_one", [step("POST", rp(RS(101)), {"action": "issue", "ownershipVerified": 1})])
r("decline_ignores_ownership", [decline(RS(101))])
