r("decline_a_request_with_no_player", [decline(RS(106))])
r("decline_twice", [decline(RS(101)), decline(RS(101))])
r("decline_then_issue", [decline(RS(101)), issue(RS(101))])
r("decline_an_issued_request", [decline(RS(102))])
r("issue_a_declined_request", [issue(RS(103))])
r("decline_a_declined_request", [decline(RS(103))])
r("issue_a_request_with_no_player", [issue(RS(106))])
r("issue_a_request_of_a_player_with_no_account", [issue(RS(107))])
r("issue_a_request_whose_email_moved", [issue(RS(101))], scenario="email_moved")
r("issue_a_disabled_account", [issue(RS(101))], scenario="disabled")
r("issue_an_account_whose_sync_failed", [issue(RS(101))], scenario="sync_failed")
r("issue_an_account_still_applying", [issue(RS(101))], scenario="sync_applying")
r("issue_an_account_of_another_sign_in", [issue(RS(101))], scenario="other_provider")
r("issue_unknown_request", [issue("b3000000-0000-4000-8000-0000000000ff")])
r("decline_unknown_request", [decline("b3000000-0000-4000-8000-0000000000ff")])
r("issue_id_is_not_a_uuid", [issue("not-a-request")])
r("decline_id_is_not_a_uuid", [decline("not-a-request")])
r("issue_id_is_braced", [issue("{%s}" % RS(101))])
for n, action in [("empty", ""), ("unknown", "approve"), ("upper_case", "ISSUE"), ("padded", " issue ")]:
    r("action_" + n, [step("POST", rp(RS(101)), {"action": action, "ownershipVerified": True})])
for n, action in [("missing", "__absent__"), ("number", 1), ("null", None), ("array", ["issue"])]:
    body = {"ownershipVerified": True} if action == "__absent__" else {"action": action, "ownershipVerified": True}
    r("action_" + n, [step("POST", rp(RS(101)), body)])
r("validation_comes_before_the_lookup", [step("POST", rp("b3000000-0000-4000-8000-0000000000ff"), {"action": "x"})])
