r("issue_ignores_unknown_fields", [issue(RS(101), ok=True) | {"body": {"action": "issue", "ownershipVerified": True, "token": "x", "playerId": ALICE}}], redact=REV)
for n, raw in [("empty", ""), ("not_json", "not json"), ("array", "[]"), ("null", "null"), ("string", '"x"'), ("trailing_text", "{} x")]:
    r("body_" + n, [step("POST", rp(RS(101)), raw=raw)])
r("no_body", [step("POST", rp(RS(101)))])
