# ================================================================ POST /api/contact-change-requests
CP = "/api/contact-change-requests"
create = lambda body, who=OWNER, **kw: step("POST", CP, body, who=who, **kw)
NEWID = ["request.id"]


def good(**kw):
    body = {"commandId": NEWCMD(1), "playerId": HANA, "field": "email", "value": "hana.new@example.test", "reason": "She asked at the front desk"}
    for k, v in kw.items():
        if v == "__absent__":
            body.pop(k, None)
        else:
            body[k] = v
    return body


