decline_c = lambda i, who=OWNER, **kw: act("decline", i, who, **kw)
check = lambda i, who=OWNER, **kw: act("check", i, who, **kw)
retry = lambda i, who=OWNER, **kw: act("retry", i, who, **kw)
d = Cases()
