    guards(d, lambda w, fn=fn, **kw: {**fn(RQ(1), who=w), **kw}, verb)
    d("%s_unknown_request" % verb, [fn("b1000000-0000-4000-8000-0000000000ff")])
    d("%s_id_is_not_a_uuid" % verb, [fn("not-a-request")])
    d("%s_id_in_upper_case" % verb, [fn(RQ(7).upper())])
    d("%s_a_body_is_ignored" % verb, [act(verb, RQ(7), raw="not json")])
